// Deterministic SciFact "pooled sensitivity" mini-set builder for the local
// RRF k=2 vs k=60 sensitivity check.
//
// This is NOT the full BEIR SciFact benchmark and NOT a replacement for it
// — it is a small, fast, LOCAL-ONLY subset used to see whether the fusion
// constant (RRF k) matters for the current local BGE-M3 dense+sparse
// provider, before touching the production RRF_K default.
//
// Selection algorithm (fixed, deterministic, seeded — every step below is a
// pure function of the existing dataset + existing TREC run files, so
// re-running this script on unchanged inputs always produces byte-identical
// output):
//   1. Take 100 of the 300 test queries via a SHA-256-seeded deterministic
//      shuffle of ALL 300 query IDs (see seededShuffle()/selectQueryIds()),
//      then the first 100 of the shuffled order. loadDataset()'s Map
//      insertion order (and therefore a plain slice(0, 100)) tracks
//      qrels/test.tsv's row order, which is query-ID sort order — an
//      arbitrary stratum, not a random sample, and was found to bias the
//      relevant-document union (101 unique docs for the first-100 slice vs
//      106-117 for other deterministic thirds of the same 300 queries).
//      The shuffle is seeded by a fixed, published string
//      (SELECTION_SHUFFLE_SEED) so it reproduces byte-for-byte without
//      being tied to insertion order.
//   2. Union of every document referenced in those 100 queries' qrels
//      ("relevant documents", included regardless of score value).
//   3. Pad the corpus to exactly 1000 documents with hard negatives, pulled
//      round-robin across (queryId x {dense,sparse}) from the EXISTING
//      local-common-512-dense.trec / local-common-512-sparse.trec run
//      files (rank-ordered: rank 1 of query A dense, rank 1 of query A
//      sparse, rank 1 of query B dense, ... then rank 2 of query A dense,
//      ...). Only the 100 selected queries' TREC rows are considered.
//      Documents already in the relevant set are skipped. This is
//      deterministic because the TREC files are generated by the completed
//      full benchmark, content-hashed, and iterated in a fixed nested order.
//   4. If padding round-robin still leaves the corpus under 1000 documents
//      (possible if the 100 queries' pooled TREC rows contain fewer than
//      1000-|relevant| distinct docs), the builder fails instead of running
//      a benchmark on a corpus smaller than the report would claim.
//
// Every qrels row in the mini-set is checked to reference a document that
// is actually present in the mini corpus (by construction it always is,
// since relevant docs are added before negatives — this is verified, not
// assumed).
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { fetchAndValidateScifact, SCIFACT_MD5 } from './fetch-scifact.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const RUNS_DIR = resolve(__dirname, '.runs');
const CACHE_DIR = resolve(__dirname, '.cache');
const MINI_SET_DIR = resolve(CACHE_DIR, 'mini-sets');

export const MINI_SET_QUERY_COUNT = 100;
export const MINI_SET_CORPUS_SIZE = 1000;
export const HARD_NEGATIVE_SOURCES = Object.freeze([
  resolve(RUNS_DIR, 'local-common-512-dense.trec'),
  resolve(RUNS_DIR, 'local-common-512-sparse.trec'),
]);

// Fixed, published seed for the query-selection shuffle. Changing this
// string changes which 100 of 300 queries are selected — it must never be
// derived from anything that varies run to run (a timestamp, a random
// value, process state).
export const SELECTION_SHUFFLE_SEED = 'semidex-beir-scifact-rrf-mini-v1';
export const SELECTION_SCHEMA_VERSION = 2; // bump on any change to selectQueryIds()/buildMiniSet() semantics

/** Deterministic counter-mode SHA-256 stream: produces an unbounded
 * sequence of 32-bit unsigned integers from (seed, counter) so a
 * Fisher-Yates shuffle can be seeded without any external RNG dependency
 * and without depending on Node's non-cryptographic Math.random(). */
function* sha256Stream(seed) {
  let counter = 0;
  while (true) {
    const digestBuf = createHash('sha256').update(`${seed}:${counter}`).digest();
    for (let i = 0; i + 4 <= digestBuf.length; i += 4) {
      yield digestBuf.readUInt32BE(i);
    }
    counter += 1;
  }
}

/** Deterministic Fisher-Yates shuffle seeded by `seed`. Same seed + same
 * ordered input array always produces the same output order. Callers that
 * need insertion-order independence must canonicalize before calling it;
 * selectQueryIds() does that below. */
export function seededShuffle(items, seed) {
  const arr = [...items];
  const stream = sha256Stream(seed);
  for (let i = arr.length - 1; i > 0; i--) {
    const rand = stream.next().value / 0x100000000; // uint32 -> [0, 1)
    const j = Math.floor(rand * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

/** Selects `count` query IDs out of `allQueryIds` via the seeded shuffle,
 * sorted to a canonical starting order first so the shuffle's result does
 * not itself depend on the caller's (insertion-order-derived) iteration
 * order — only on the seed and the SET of IDs. */
export function selectQueryIds(allQueryIds, count, seed = SELECTION_SHUFFLE_SEED) {
  const canonical = [...allQueryIds].sort();
  return seededShuffle(canonical, seed).slice(0, count);
}

/** Parses a TREC run file into Map<queryId, docId[]> ordered by rank
 * (ascending — rank 1 first). Format: "qid Q0 docid rank score runtag". */
export function parseTrecRun(text) {
  const byQuery = new Map();
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const parts = trimmed.split(/\s+/);
    if (parts.length < 6) continue;
    const [qid, , docId, rankRaw] = parts;
    const rank = Number(rankRaw);
    if (!byQuery.has(qid)) byQuery.set(qid, []);
    byQuery.get(qid).push({ docId, rank });
  }
  for (const arr of byQuery.values()) arr.sort((a, b) => a.rank - b.rank);
  return byQuery;
}

/**
 * Builds the deterministic mini-set from an already-loaded full dataset
 * (corpus/queries/qrels, as returned by fetch-scifact.mjs's loadDataset())
 * plus the two existing local-common-512 TREC run files as the hard
 * negative pool. Pure function of its inputs — no I/O beyond the TREC file
 * reads the caller already resolved into `trecRunsByFile`.
 */
export function buildMiniSet({ corpus, queries, qrels, trecRunsByFile, queryCount = MINI_SET_QUERY_COUNT, corpusSize = MINI_SET_CORPUS_SIZE, selectionSeed = SELECTION_SHUFFLE_SEED }) {
  const allQueryIds = [...queries.keys()];
  const selectedQueryIds = selectQueryIds(allQueryIds, queryCount, selectionSeed);

  // Step 2: relevant-document union.
  const relevantDocIds = new Set();
  for (const qid of selectedQueryIds) {
    const qr = qrels.get(qid);
    if (!qr) continue;
    for (const docId of qr.keys()) relevantDocIds.add(docId);
  }

  const miniDocIds = new Set(relevantDocIds);

  // Step 3: round-robin hard-negative padding across (query x trecFile),
  // rank-ascending within each (query, file) pair.
  const cursors = selectedQueryIds.map((qid) => trecRunsByFile.map(() => 0)); // [queryIdx][fileIdx] -> next index into that query's ranked list
  let exhausted = false;
  let round = 0;
  const negativesAdded = [];
  while (miniDocIds.size < corpusSize && !exhausted) {
    // A round can consume only duplicate/foreign candidates (advancing
    // cursors without adding a new doc) while genuinely unique candidates
    // still remain deeper in some other query's ranked list. Stopping
    // purely on "no doc added this round" would exit early in that case.
    // Termination must instead track whether ANY cursor still advanced —
    // once every cursor has reached the end of its ranked list, no round
    // can ever add anything, so termination is guaranteed within
    // (sum of all ranked-list lengths) rounds regardless.
    let anyCursorAdvanced = false;
    for (let qi = 0; qi < selectedQueryIds.length; qi++) {
      const qid = selectedQueryIds[qi];
      for (let fi = 0; fi < trecRunsByFile.length; fi++) {
        if (miniDocIds.size >= corpusSize) break;
        const ranked = trecRunsByFile[fi].get(qid) ?? [];
        const cursor = cursors[qi][fi];
        if (cursor >= ranked.length) continue;
        const candidate = ranked[cursor];
        cursors[qi][fi] += 1;
        anyCursorAdvanced = true;
        if (!candidate) continue;
        if (miniDocIds.has(candidate.docId)) continue; // already relevant or already added
        if (!corpus.has(candidate.docId)) continue; // defensive: TREC row must reference a real corpus doc
        miniDocIds.add(candidate.docId);
        negativesAdded.push({ docId: candidate.docId, fromQueryId: qid, fromFile: fi, rank: candidate.rank, round });
      }
    }
    round += 1;
    if (!anyCursorAdvanced) exhausted = true;
  }

  const shortfall = Math.max(0, corpusSize - miniDocIds.size);

  const miniCorpus = new Map();
  for (const docId of miniDocIds) miniCorpus.set(docId, corpus.get(docId));

  const miniQueries = new Map(selectedQueryIds.map((qid) => [qid, queries.get(qid)]));
  const miniQrels = new Map();
  for (const qid of selectedQueryIds) {
    const qr = qrels.get(qid);
    if (qr) miniQrels.set(qid, new Map(qr));
  }

  // Verify: no qrels row in the mini-set references a document absent from
  // the mini corpus.
  const danglingQrelsRefs = [];
  for (const [qid, docsMap] of miniQrels.entries()) {
    for (const docId of docsMap.keys()) {
      if (!miniCorpus.has(docId)) danglingQrelsRefs.push({ qid, docId });
    }
  }

  return {
    corpus: miniCorpus,
    queries: miniQueries,
    qrels: miniQrels,
    stats: {
      selectedQueryCount: selectedQueryIds.length,
      relevantDocCount: relevantDocIds.size,
      negativeDocCount: negativesAdded.length,
      totalCorpusSize: miniCorpus.size,
      requestedCorpusSize: corpusSize,
      shortfall,
      danglingQrelsRefs,
    },
  };
}

function digest(obj) {
  return createHash('sha256').update(JSON.stringify(obj)).digest('hex').slice(0, 16);
}

function sha256OfFile(path) {
  return createHash('sha256').update(readFileSync(path)).digest('hex');
}

/** Hashes of the TREC source files' actual CONTENT, not their paths.
 * A cache key built only from HARD_NEGATIVE_SOURCES' paths (the original
 * bug) would silently keep serving a stale mini-set if either TREC file
 * were regenerated by a later full benchmark run with the same filename —
 * hashing content makes that impossible: any byte change invalidates the
 * cache automatically. */
function hardNegativeSourceHashes() {
  return HARD_NEGATIVE_SOURCES.map((path) => ({ path: path.replace(RUNS_DIR, '.runs'), sha256: sha256OfFile(path) }));
}

export function miniSetCachePath({ datasetMd5, queryCount, corpusSize, selectionSeed, sourceHashes }) {
  mkdirSync(MINI_SET_DIR, { recursive: true });
  const key = digest({
    schemaVersion: SELECTION_SCHEMA_VERSION,
    datasetMd5,
    queryCount,
    corpusSize,
    selectionSeed,
    sourceHashes,
  });
  return resolve(MINI_SET_DIR, `rrf-mini-${key}.json`);
}

function serializeMiniSet(miniSet, manifest) {
  return {
    manifest,
    corpus: [...miniSet.corpus.entries()],
    queries: [...miniSet.queries.entries()],
    qrels: [...miniSet.qrels.entries()].map(([qid, docsMap]) => [qid, [...docsMap.entries()]]),
    stats: miniSet.stats,
  };
}

function deserializeMiniSet(raw) {
  return {
    corpus: new Map(raw.corpus),
    queries: new Map(raw.queries),
    qrels: new Map(raw.qrels.map(([qid, entries]) => [qid, new Map(entries)])),
    stats: raw.stats,
  };
}

/** Revalidates both freshly built and cached mini-sets. Cache manifests
 * prove which inputs produced a file, but they do not prove that the file
 * is complete or was not truncated/edited after it was written. */
export function validateMiniSet(miniSet, {
  queryCount = MINI_SET_QUERY_COUNT,
  corpusSize = MINI_SET_CORPUS_SIZE,
} = {}) {
  const errors = [];
  if (!(miniSet?.corpus instanceof Map)) errors.push('corpus is not a Map');
  if (!(miniSet?.queries instanceof Map)) errors.push('queries is not a Map');
  if (!(miniSet?.qrels instanceof Map)) errors.push('qrels is not a Map');
  if (!miniSet?.stats || typeof miniSet.stats !== 'object') errors.push('stats are missing');
  if (errors.length > 0) return errors;

  if (miniSet.corpus.size !== corpusSize) {
    errors.push(`corpus size is ${miniSet.corpus.size}, expected ${corpusSize}`);
  }
  if (miniSet.queries.size !== queryCount) {
    errors.push(`query count is ${miniSet.queries.size}, expected ${queryCount}`);
  }
  if (miniSet.stats.totalCorpusSize !== miniSet.corpus.size) {
    errors.push(`stats.totalCorpusSize is ${miniSet.stats.totalCorpusSize}, actual corpus size is ${miniSet.corpus.size}`);
  }
  if (miniSet.stats.requestedCorpusSize !== corpusSize) {
    errors.push(`stats.requestedCorpusSize is ${miniSet.stats.requestedCorpusSize}, expected ${corpusSize}`);
  }
  if (miniSet.stats.selectedQueryCount !== miniSet.queries.size) {
    errors.push(`stats.selectedQueryCount is ${miniSet.stats.selectedQueryCount}, actual query count is ${miniSet.queries.size}`);
  }
  if (miniSet.stats.relevantDocCount + miniSet.stats.negativeDocCount !== miniSet.corpus.size) {
    errors.push('relevantDocCount + negativeDocCount does not equal the actual corpus size');
  }
  if (miniSet.stats.shortfall !== 0) {
    errors.push(`corpus shortfall is ${miniSet.stats.shortfall}`);
  }

  let danglingCount = 0;
  for (const [queryId, docsMap] of miniSet.qrels) {
    if (!miniSet.queries.has(queryId)) errors.push(`qrels contain unselected query ${queryId}`);
    if (!(docsMap instanceof Map)) {
      errors.push(`qrels for ${queryId} are not a Map`);
      continue;
    }
    for (const docId of docsMap.keys()) {
      if (!miniSet.corpus.has(docId)) danglingCount += 1;
    }
  }
  if (danglingCount > 0) errors.push(`${danglingCount} qrels rows reference documents absent from the mini corpus`);

  return errors;
}

function sameManifest(left, right) {
  return JSON.stringify(left) === JSON.stringify(right);
}

/**
 * Strictly offline loader: reads ONLY the already-written mini-set cache
 * file (content/revision-addressed — see miniSetCachePath()) and
 * revalidates it with validateMiniSet(). Never calls
 * fetchAndValidateScifact() or anything else that could reach the network
 * — unlike buildAndCacheMiniSet() below, which always loads/validates the
 * full SciFact dataset first (a network call in principle, even though it
 * is a no-op when a valid local cache already satisfies it). Callers that
 * must guarantee zero network access (e.g. offline analysis tooling)
 * should use this function instead.
 *
 * Throws a clear, actionable error if the cache is absent, corrupt, or
 * fails validation — it never rebuilds, and never falls back to fetching.
 */
export function loadCachedMiniSet() {
  const sourceHashes = hardNegativeSourceHashes();
  const manifest = {
    schemaVersion: SELECTION_SCHEMA_VERSION,
    datasetMd5: SCIFACT_MD5,
    queryCount: MINI_SET_QUERY_COUNT,
    corpusSize: MINI_SET_CORPUS_SIZE,
    selectionSeed: SELECTION_SHUFFLE_SEED,
    sourceHashes,
  };
  const cachePath = miniSetCachePath({
    datasetMd5: SCIFACT_MD5, queryCount: MINI_SET_QUERY_COUNT, corpusSize: MINI_SET_CORPUS_SIZE,
    selectionSeed: SELECTION_SHUFFLE_SEED, sourceHashes,
  });

  if (!existsSync(cachePath)) {
    throw new Error(`[build-rrf-mini-set] no cached mini-set found at ${cachePath} — run "node benchmarks/external/beir/build-rrf-mini-set.mjs" (or run-rrf-mini.mjs) online first to produce it; this loader never fetches over the network.`);
  }

  let raw;
  try {
    raw = JSON.parse(readFileSync(cachePath, 'utf-8'));
  } catch (err) {
    throw new Error(`[build-rrf-mini-set] cached mini-set at ${cachePath} is not valid JSON (${err.message}) — regenerate it online; this loader never rebuilds or fetches.`);
  }
  if (!raw.manifest || !sameManifest(raw.manifest, manifest)) {
    throw new Error(`[build-rrf-mini-set] cached mini-set at ${cachePath} has a manifest that does not match the current pinned dataset/selection/source hashes — regenerate it online; this loader never rebuilds or fetches.`);
  }

  const cached = deserializeMiniSet(raw);
  const validationErrors = validateMiniSet(cached);
  if (validationErrors.length > 0) {
    throw new Error(`[build-rrf-mini-set] cached mini-set at ${cachePath} failed validation: ${validationErrors.join('; ')} — regenerate it online; this loader never rebuilds or fetches.`);
  }

  return { ...cached, cachePath, fromCache: true, manifest: raw.manifest };
}

/** Full pipeline: load the validated full SciFact dataset, load the two
 * hard-negative TREC source files, build the deterministic mini-set, and
 * write it to a gitignored cache keyed by dataset MD5 + selection params +
 * the TREC source files' actual CONTENT hashes (not their paths — a
 * path-only key would silently keep serving a stale mini-set if either
 * TREC file's content changed under the same filename). Throws if any
 * qrels row in the built mini-set dangles, or if the corpus padding fell
 * short of the target size — both are fatal, not warnings: a short corpus
 * is not the fixed 1000-document design this benchmark's report claims to
 * measure, and reporting a verdict from it would be misleading. */
export async function buildAndCacheMiniSet({ log = () => {}, useCache = true } = {}) {
  const { corpus, queries, qrels } = await fetchAndValidateScifact({ log });
  const sourceHashes = hardNegativeSourceHashes();
  const manifest = {
    schemaVersion: SELECTION_SCHEMA_VERSION,
    datasetMd5: SCIFACT_MD5,
    queryCount: MINI_SET_QUERY_COUNT,
    corpusSize: MINI_SET_CORPUS_SIZE,
    selectionSeed: SELECTION_SHUFFLE_SEED,
    sourceHashes,
  };
  const cachePath = miniSetCachePath({
    datasetMd5: SCIFACT_MD5, queryCount: MINI_SET_QUERY_COUNT, corpusSize: MINI_SET_CORPUS_SIZE,
    selectionSeed: SELECTION_SHUFFLE_SEED, sourceHashes,
  });

  if (useCache) {
    try {
      const raw = JSON.parse(readFileSync(cachePath, 'utf-8'));
      if (raw.manifest && sameManifest(raw.manifest, manifest)) {
        const cached = deserializeMiniSet(raw);
        const validationErrors = validateMiniSet(cached);
        if (validationErrors.length === 0) {
          log(`[build-rrf-mini-set] cache hit: ${cachePath}`);
          return { ...cached, cachePath, fromCache: true, manifest: raw.manifest };
        }
        log(`[build-rrf-mini-set] cache failed validation (${validationErrors.join('; ')}) — rebuilding`);
      } else {
        log('[build-rrf-mini-set] cache file present but manifest mismatch — rebuilding');
      }
    } catch { /* fall through to build */ }
  }

  const trecRunsByFile = HARD_NEGATIVE_SOURCES.map((path) => parseTrecRun(readFileSync(path, 'utf-8')));
  const miniSet = buildMiniSet({ corpus, queries, qrels, trecRunsByFile });

  const validationErrors = validateMiniSet(miniSet);
  if (validationErrors.length > 0) {
    throw new Error(`[build-rrf-mini-set] invalid mini-set: ${validationErrors.join('; ')} — refusing to run the benchmark`);
  }

  log(`[build-rrf-mini-set] built: ${miniSet.stats.selectedQueryCount} queries, ${miniSet.stats.relevantDocCount} relevant docs, ${miniSet.stats.negativeDocCount} hard negatives, ${miniSet.stats.totalCorpusSize} total docs`);

  writeFileSync(cachePath, JSON.stringify(serializeMiniSet(miniSet, manifest)), 'utf-8');
  log(`[build-rrf-mini-set] cache written: ${cachePath}`);

  return { ...miniSet, cachePath, fromCache: false, manifest };
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  try {
    const miniSet = await buildAndCacheMiniSet({ log: (m) => console.log(m) });
    console.log(JSON.stringify(miniSet.stats, null, 2));
    process.exitCode = miniSet.stats.danglingQrelsRefs.length > 0 ? 1 : 0;
  } catch (err) {
    console.error(err.message);
    process.exitCode = 1;
  }
}
